public class audit_model{public static void main(String[]a)throws Exception{try(CubismMoc moc=CubismMoc.instantiate(Files.readAllBytes(Path.of(a[0])));CubismModel m=moc.instantiateModel()){for(var p:m.getParameterViews())p.setValue(p.getDefaultValue());m.update();StringBuilder b=new StringBuilder("{\"drawables\":[");boolean first=true;for(var d:m.getDrawableViews()){if(!first)b.append(',');first=false;b.append("{\"id\":\"").append(d.getId()).append("\",\"blendMode\":").append(d.getBlendMode()).append(",\"flags\":").append(d.getConstantFlag()).append(",\"multiply\":").append(Arrays.toString(d.getMultiplyColors())).append(",\"screen\":").append(Arrays.toString(d.getScreenColors())).append(",\"masks\":").append(Arrays.toString(d.getMasks())).append(",\"opacity\":").append(d.getOpacity()).append('}');}b.append("]}");Files.writeString(Path.of(a[1]),b.toString());}}}